code = '''from collections import deque


def transform(grid):
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])
    runs = []

    for r in range(h):
        c = 0
        while c < w:
            if src[r][c] != 5:
                c += 1
                continue
            c0 = c
            while c < w and src[r][c] == 5:
                c += 1
            if c - c0 >= 2:
                runs.append(("h", r, c0, c - 1))

    for c in range(w):
        r = 0
        while r < h:
            if src[r][c] != 5:
                r += 1
                continue
            r0 = r
            while r < h and src[r][c] == 5:
                r += 1
            if r - r0 >= 2:
                runs.append(("v", c, r0, r - 1))

    for orient, fixed, start, end in runs:
        if orient == "v":
            sides = [(fixed - 1, 0), (fixed + 1, 0)]
            seeds = [(r, c) for c, _ in sides if 0 <= c < w
                     for r in range(start, end + 1)
                     if src[r][c] not in (0, 5)]
        else:
            sides = [(fixed - 1, 0), (fixed + 1, 0)]
            seeds = [(r, c) for r, _ in sides if 0 <= r < h
                     for c in range(start, end + 1)
                     if src[r][c] not in (0, 5)]

        seen = set()
        for seed in seeds:
            if seed in seen:
                continue
            q = deque([seed])
            seen.add(seed)
            component = []
            while q:
                r, c = q.popleft()
                component.append((r, c))
                for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if (0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen
                            and src[nr][nc] not in (0, 5)):
                        seen.add((nr,nc))
                        q.append((nr,nc))
            r0 = min(r for r, c in component)
            r1 = max(r for r, c in component)
            c0 = min(c for r, c in component)
            c1 = max(c for r, c in component)
            tile_h, tile_w = r1-r0+1, c1-c0+1

            if orient == "v":
                for r in range(start, end + 1):
                    tr = r0 + (r-r0) % tile_h
                    for c in range(c0, c1 + 1):
                        out[r][c] = src[tr][c]
            else:
                for c in range(start, end + 1):
                    tc = c0 + (c-c0) % tile_w
                    for r in range(r0, r1 + 1):
                        out[r][c] = src[r][tc]
    return out
'''
